'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');

function check(tree, values) {
  // Search first: materializing the leaves must not hide stale lazy tags.
  for (let lo = 0; lo <= values.length; lo++) {
    for (const x of [-Infinity, -30, -1, 0, 1, 15, 30, Infinity]) {
      assert.equal(tree.firstAtLeast(lo, x), values.findIndex((v, i) => i >= lo && v >= x));
    }
  }
  for (let l = 0; l <= values.length; l++) {
    let sum = 0;
    let max = -Infinity;
    for (let r = l; r <= values.length; r++) {
      assert.equal(tree.max(l, r), max);
      assert.equal(tree.sum(l, r), sum);
      if (r < values.length) {
        sum += values[r];
        max = Math.max(max, values[r]);
      }
    }
  }
  for (let i = 0; i < values.length; i++) assert.equal(tree.get(i), values[i]);
  assert.deepEqual(tree.toArray(), values);
}

test('assignment replaces pending additions at parents and descendants', () => {
  const tree = new RangeTree([1, 2, 3, 4, 5, 6, 7, 8]);
  tree.add(0, 4, 11);
  tree.add(4, 8, -7);
  tree.add(0, 8, 3);
  tree.assign(0, 8, -10);
  tree.add(0, 8, 2);
  tree.assign(2, 6, 0);
  tree.add(3, 7, -5);
  check(tree, [-8, -8, 0, -5, -5, -5, -13, -8]);
});

test('threshold search propagates both lazy operations and respects lo', () => {
  const tree = new RangeTree([0, 0, 0, 0, 0]);
  tree.add(0, 5, 5);
  assert.equal(tree.firstAtLeast(0, 5), 0);
  tree.assign(0, 5, 9);
  assert.equal(tree.firstAtLeast(3, 9), 3);
  tree.assign(0, 2, -8);
  tree.assign(2, 5, 4);
  tree.add(0, 5, -1);
  assert.equal(tree.firstAtLeast(0, 3), 2);
  assert.equal(tree.firstAtLeast(3, 3), 3);
  assert.equal(tree.firstAtLeast(0, 4), -1);
  check(tree, [-9, -9, 3, 3, 3]);
});

test('deterministic mixed workloads agree with an array model', () => {
  let state = 0x8a1d73;
  const random = n => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % n;
  };
  for (const n of [1, 2, 3, 5, 8, 17, 33]) {
    const values = Array.from({ length: n }, () => random(41) - 20);
    const tree = new RangeTree(values);
    check(tree, values);
    for (let round = 0; round < 100; round++) {
      // Batch updates without reads to exercise composition across tree levels.
      for (let step = 0; step < 12; step++) {
        let l = random(n + 1);
        let r = random(n + 1);
        if (l > r) [l, r] = [r, l];
        if (step % 4 === 0) { l = 0; r = n; }
        const v = random(41) - 20;
        if (random(2)) {
          assert.equal(tree.assign(l, r, v), undefined);
          for (let i = l; i < r; i++) values[i] = v;
        } else {
          assert.equal(tree.add(l, r, v), undefined);
          for (let i = l; i < r; i++) values[i] += v;
        }
      }
      check(tree, values);
    }
  }
});

test('validation, empty ranges, read-only length, and independent arrays', () => {
  for (const input of [[], null, undefined, {}, new Float64Array([1]), [NaN], [Infinity], [-Infinity], ['1'], [1, , 2]]) {
    assert.throws(() => new RangeTree(input), RangeError);
  }
  const input = [-5, 2, 7];
  const tree = new RangeTree(input);
  input[0] = 100;
  assert.equal(tree.length, 3);
  assert.throws(() => { tree.length = 1; }, TypeError);
  tree.add(0, 3, -2);
  const expected = [-7, 0, 5];
  for (const [l, r] of [[-1, 1], [0, 4], [2, 1], [0.5, 1], [0, 1.5], [NaN, 2], [0, Infinity], ['0', 1], [0, undefined]]) {
    for (const method of ['assign', 'add', 'sum', 'max']) {
      assert.throws(() => tree[method](l, r, 10), RangeError);
    }
  }
  for (const v of [NaN, Infinity, -Infinity, '1', null, undefined]) {
    for (const method of ['assign', 'add']) {
      assert.throws(() => tree[method](0, 3, v), RangeError);
      assert.throws(() => tree[method](1, 1, v), RangeError);
    }
  }
  for (const i of [-1, 3, 0.5, NaN, Infinity, '0', undefined]) {
    assert.throws(() => tree.get(i), RangeError);
  }
  for (const lo of [-1, 4, 0.5, NaN, Infinity, '0', undefined]) {
    assert.throws(() => tree.firstAtLeast(lo, 0), RangeError);
  }
  for (const x of [NaN, '0', null, undefined]) {
    assert.throws(() => tree.firstAtLeast(0, x), RangeError);
  }
  for (let i = 0; i <= tree.length; i++) {
    assert.equal(tree.assign(i, i, 12), undefined);
    assert.equal(tree.add(i, i, 12), undefined);
    assert.equal(tree.sum(i, i), 0);
    assert.equal(tree.max(i, i), -Infinity);
  }
  check(tree, expected);
  const output = tree.toArray();
  output[0] = 100;
  assert.deepEqual(tree.toArray(), expected);
  tree.assign(0, 3, 0);
  assert.deepEqual(output, [100, 0, 5]);
  check(tree, [0, 0, 0]);
});

test('lazy traversal retains logarithmic operations and linear materialization', () => {
  const n = 65537;
  const tree = new RangeTree(new Array(n).fill(-1));
  const methods = ['_update', '_sum', '_max', '_first', '_write'];
  const counts = Object.fromEntries(methods.map(name => [name, 0]));
  for (const name of methods) {
    const original = tree[name];
    tree[name] = function (...args) { counts[name]++; return original.apply(this, args); };
  }
  tree.add(0, n, 5);
  tree.assign(1, n - 1, -9);
  tree.add(123, n - 123, 2);
  assert.equal(tree.sum(122, 125), -23);
  assert.equal(tree.max(1, n - 1), -7);
  assert.equal(tree.firstAtLeast(1, 0), n - 1);
  assert.equal(tree.get(n - 1), 4);
  for (const name of methods.slice(0, 4)) assert.ok(counts[name] < 20 * Math.ceil(Math.log2(n)), `${name}: ${counts[name]}`);
  const output = tree.toArray();
  assert.equal(counts._write, 2 * n - 1);
  assert.equal(output[0], 4);
  assert.equal(output[122], -9);
  assert.equal(output[123], -7);
  assert.equal(output[n - 1], 4);
});
